Refactor the following JavaScript to use async/await instead of callbacks, keep behavior identical, add JSDoc comments, and return the complete refactored file.

```js
const fs = require('fs');
const path = require('path');
const https = require('https');

function readConfig(dir, cb) {
  fs.readFile(path.join(dir, 'config.json'), 'utf8', function (err, data) {
    if (err) return cb(err);
    let cfg;
    try { cfg = JSON.parse(data); } catch (e) { return cb(e); }
    if (!cfg.endpoint) return cb(new Error('missing endpoint'));
    cb(null, cfg);
  });
}

function fetchJson(url, cb) {
  https.get(url, function (res) {
    if (res.statusCode !== 200) {
      res.resume();
      return cb(new Error('HTTP ' + res.statusCode));
    }
    let body = '';
    res.setEncoding('utf8');
    res.on('data', function (chunk) { body += chunk; });
    res.on('end', function () {
      try { cb(null, JSON.parse(body)); } catch (e) { cb(e); }
    });
  }).on('error', cb);
}

function writeReport(dir, items, cb) {
  const lines = items.map(function (it) { return it.id + '\t' + it.name + '\t' + it.score; });
  fs.writeFile(path.join(dir, 'report.tsv'), lines.join('\n'), function (err) {
    if (err) return cb(err);
    cb(null, lines.length);
  });
}

function run(dir, cb) {
  readConfig(dir, function (err, cfg) {
    if (err) return cb(err);
    fetchJson(cfg.endpoint + '/items', function (err, items) {
      if (err) return cb(err);
      const filtered = items.filter(function (it) { return it.score >= (cfg.minScore || 0); });
      filtered.sort(function (a, b) { return b.score - a.score; });
      writeReport(dir, filtered, function (err, n) {
        if (err) return cb(err);
        cb(null, { written: n, skipped: items.length - n });
      });
    });
  });
}

module.exports = { readConfig, fetchJson, writeReport, run };
